// xonsh: backend (arguments are Python string literals) + emitter (plain Python 3 run by xonsh).
#include "shell.hpp"
#include "emit_dialect.hpp"
#include <cstdio>
#include <set>
namespace {
using namespace forge::script;
std::string py(const std::string& s) {
    std::string o = "'";
    for (unsigned char c : s) {
        if (c == '\'' || c == '\\') { o += '\\'; o += char(c); }
        else if (c == '\n') o += "\\n"; else if (c == '\r') o += "\\r"; else if (c == '\t') o += "\\t";
        else if (c < 0x20 || c == 0x7f) { char b[8]; std::snprintf(b, sizeof b, "\\x%02x", c); o += b; }
        else o += char(c);
    }
    return o + "'";
}
struct py_dialect : block_dialect {
    std::set<std::string> need, fn_globals;
    std::size_t gline = 0;
    py_dialect() { noop = "pass"; }
    std::string header() override {
        std::string h = "#!/usr/bin/env xonsh\n# generated by `forge script --emit " + cx->target + "`; runs without FORGE (plain Python 3 under xonsh)\nimport os, sys, shutil, shlex, subprocess\n";
        if (need.count("div")) h += "def _div(a, b):\n    q = abs(a) // abs(b)\n    return q if (a < 0) == (b < 0) else -q\n";
        if (need.count("platform")) h += "def _platform():\n    p = sys.platform\n    if p.startswith('win'): return 'windows'\n    if p == 'darwin': return 'macos'\n    if p.startswith('freebsd'): return 'freebsd'\n    if p.startswith('linux'): return 'android' if 'ANDROID_ROOT' in os.environ else 'linux'\n    return 'other'\n";
        h += "def _rm(p):\n    if os.path.isdir(p) and not os.path.islink(p): shutil.rmtree(p, ignore_errors=True)\n    elif os.path.lexists(p): os.remove(p)\n";
        return h;
    }
    std::string s_lit(const std::string& s) override { return py(s); }
    std::string ref(const std::string& n, ety, bool) override { return n; }
    std::string arith(char op, const std::string& a, const std::string& b) override {
        if (op == '/') { need.insert("div"); return "_div(" + a + ", " + b + ")"; }
        if (op == '%') { need.insert("div"); return "((" + a + ") - (" + b + ") * _div(" + a + ", " + b + "))"; }
        return "(" + a + " " + op + " " + b + ")";
    }
    std::string neg(const std::string& a) override { return "(-" + a + ")"; }
    std::string concat(const std::vector<std::string>& p) override { std::string o = "("; for (std::size_t i = 0; i < p.size(); ++i) o += (i ? " + " : "") + p[i]; return o + ")"; }
    std::string i2s(const std::string& i) override { return "str(" + i + ")"; }
    std::string s2i(const std::string& s) override { return "int(" + s + ")"; }
    std::string slen(const std::string& s) override { return "len(" + s + ".encode())"; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool) override { return "(" + a + " " + op + " " + b + ")"; }
    std::string c_and(const std::string& a, const std::string& b) override { return "(" + a + " and " + b + ")"; }
    std::string c_or(const std::string& a, const std::string& b) override { return "(" + a + " or " + b + ")"; }
    std::string c_not(const std::string& a) override { return "(not " + a + ")"; }
    std::string c_bool(bool v) override { return v ? "True" : "False"; }
    std::string truthy(const std::string& v) override { return "(" + v + " == 'true')"; }
    void let(const std::string& n, const std::string& v, ety, bool global, bool) override { if (global && cx->in_fn) fn_globals.insert(n); L(n + " = " + v); }
    void print(const std::string& v, bool nl, bool err) override { L("print(" + v + (nl ? "" : ", end=''") + (err ? ", file=sys.stderr" : "") + ", flush=True)"); }
    void if_(const std::string& c) override { open("if " + c + ":"); }
    void else_() override { mid("else:"); }
    void end_if() override { close(""); cx->lines.pop_back(); }
    void while_(const std::string& c) override { open("while " + c + ":"); }
    void end_while() override { end_if(); }
    void for_(const std::string& v, const std::vector<std::string>& items) override { std::string s; for (auto& i : items) s += (s.empty() ? "" : ", ") + i; open("for " + v + " in [" + s + "]:"); }
    void end_for() override { end_if(); }
    void brk() override { L("break"); }
    void cont() override { L("continue"); }
    void fn_(const std::string& name, const std::vector<std::string>& ps) override {
        std::string s; for (auto& p : ps) s += (s.empty() ? "" : ", ") + p;
        open("def " + name + "(" + s + "):"); L("pass"); gline = cx->lines.size() - 1; fn_globals.clear();
    }
    void end_fn() override {
        if (!fn_globals.empty()) { std::string g; for (auto& n : fn_globals) g += (g.empty() ? "" : ", ") + n; auto& l = cx->lines[gline]; l = l.substr(0, l.size() - 4) + "global " + g; }
        end_if();
    }
    void ret(const std::string& v) override { L(v.empty() ? "return" : "return " + v); }
    std::string call(const std::string& name, const std::vector<std::string>& a, bool want, ety) override {
        std::string s = name + "("; for (std::size_t i = 0; i < a.size(); ++i) s += (i ? ", " : "") + a[i]; s += ")";
        if (!want) { L(s); return ""; }
        return s;
    }
    void exit_(const std::string& c) override { L("sys.exit(" + c + ")"); }
    std::string env(const std::string& n, const std::string& d) override { return "os.environ.get(" + n + ", " + d + ")"; }
    void setenv(const std::string& n, const std::string& v) override { L("os.environ[" + n + "] = " + v); }
    std::string test_path(const std::string& p, char k) override { return std::string("os.path.") + (k == 'd' ? "isdir(" : k == 'f' ? "isfile(" : "exists(") + p + ")"; }
    void mkdir(const std::string& p) override { L("os.makedirs(" + p + ", exist_ok=True)"); }
    void remove(const std::string& p) override { L("_rm(" + p + ")"); }
    void write(const std::string& p, const std::string& s, bool app) override { L(std::string("with open(") + p + (app ? ", 'ab'" : ", 'wb'") + ") as _f: _f.write(" + s + ".encode())"); }
    std::string read(const std::string& p) override { return "open(" + p + ", 'rb').read().decode()"; }
    std::string cwd() override { return "os.getcwd()"; }
    std::string platform() override { need.insert("platform"); return "_platform()"; }
    void run(const std::string& cmd, const std::string& o, const std::string& c, bool host) override {
        L("_p = subprocess.run(" + std::string(host ? "['xonsh', '--no-rc', '-c', " : "['sh', '-c', ") + cmd + "], stdout=subprocess.PIPE, env=dict(os.environ))");
        L(o + " = _p.stdout.decode()");
        L(c + " = _p.returncode");
    }
    std::string sh_quote(const std::string& v) override { return "shlex.quote(" + v + ")"; }
};
} // namespace
void forge_shell_register_xonsh(forge::script::shell_registry& r) {
    forge::script::shell_backend b; b.name = "xonsh"; b.exes = {"xonsh"}; b.family = "python"; b.golden_tested = true;
    b.argv = [](const std::string& exe, const std::string& sc) -> std::vector<std::string> { return {exe, "--no-rc", "-c", sc}; };
    b.quote = [](const std::string& s) { std::string o = "'"; for (char c : s) { if (c == '\'' || c == '\\') o += '\\'; if (c == '\n') { o += "\\n"; continue; } o += c; } return o + "'"; };
    b.emitter = [] { return std::make_unique<py_dialect>(); }; b.emit_ext = ".xsh"; b.emit_tested = true;
    r.add(std::move(b));
}
